func (e *LogRecordEncoder) Reset() {
	// Since we are resetting the state of encoder make sure the next Encode()
	// call forcedly writes all fields and does not attempt to skip.
	e.forceModifiedFields = e.keepFieldMask

	if e.fieldCount <= 0 {
		return // TimeUnixNano and all subsequent fields are skipped.
	}
	e.timeUnixNanoEncoder.Reset()
	if e.fieldCount <= 1 {
		return // ObservedTimeUnixNano and all subsequent fields are skipped.
	}
	e.observedTimeUnixNanoEncoder.Reset()
	if e.fieldCount <= 2 {
		return // SeverityNumber and all subsequent fields are skipped.
	}
	e.severityNumberEncoder.Reset()
	if e.fieldCount <= 3 {
		return // SeverityText and all subsequent fields are skipped.
	}
	e.severityTextEncoder.Reset()
	if e.fieldCount <= 4 {
		return // Body and all subsequent fields are skipped.
	}
	if !e.isBodyRecursive {
		e.bodyEncoder.Reset()
	}
	if e.fieldCount <= 5 {
		return // Attributes and all subsequent fields are skipped.
	}
	if !e.isAttributesRecursive {
		e.attributesEncoder.Reset()
	}
	if e.fieldCount <= 6 {
		return // DroppedAttributesCount and all subsequent fields are skipped.
	}
	e.droppedAttributesCountEncoder.Reset()
	if e.fieldCount <= 7 {
		return // Flags and all subsequent fields are skipped.
	}
	e.flagsEncoder.Reset()
	if e.fieldCount <= 8 {
		return // TraceID and all subsequent fields are skipped.
	}
	e.traceIDEncoder.Reset()
	if e.fieldCount <= 9 {
		return // SpanID and all subsequent fields are skipped.
	}
	e.spanIDEncoder.Reset()
	if e.fieldCount <= 10 {
		return // EventName and all subsequent fields are skipped.
	}
	e.eventNameEncoder.Reset()
}

// Encode encodes val into buf
func (e *LogRecordEncoder) Encode(val *LogRecord) {
	var bitCount uint

	// Mask that describes what fields are encoded. Start with all modified fields.
	fieldMask := val.modifiedFields.mask

	// If forceModifiedFields we need to set to 1 all bits so that we
	// force writing of all fields.
	fieldMask |= e.forceModifiedFields
	e.forceModifiedFields = 0

	// Only write fields that we want to write. See Init() for keepFieldMask.
	fieldMask &= e.keepFieldMask

	// Write bits to indicate which fields follow.
	e.buf.WriteBits(fieldMask, e.fieldCount)
	bitCount += e.fieldCount

	// Encode modified, present fields.

	if fieldMask&fieldModifiedLogRecordTimeUnixNano != 0 {
		// Encode TimeUnixNano
		e.timeUnixNanoEncoder.Encode(val.timeUnixNano)
	}

	if fieldMask&fieldModifiedLogRecordObservedTimeUnixNano != 0 {
		// Encode ObservedTimeUnixNano
		e.observedTimeUnixNanoEncoder.Encode(val.observedTimeUnixNano)
	}

	if fieldMask&fieldModifiedLogRecordSeverityNumber != 0 {
		// Encode SeverityNumber
		e.severityNumberEncoder.Encode(val.severityNumber)
	}

	if fieldMask&fieldModifiedLogRecordSeverityText != 0 {
		// Encode SeverityText
		e.severityTextEncoder.Encode(val.severityText)
	}

	if fieldMask&fieldModifiedLogRecordBody != 0 {
		// Encode Body
		e.bodyEncoder.Encode(val.body)
	}

	if fieldMask&fieldModifiedLogRecordAttributes != 0 {
		// Encode Attributes
		e.attributesEncoder.Encode(&val.attributes)
	}

	if fieldMask&fieldModifiedLogRecordDroppedAttributesCount != 0 {
		// Encode DroppedAttributesCount
		e.droppedAttributesCountEncoder.Encode(val.droppedAttributesCount)
	}

	if fieldMask&fieldModifiedLogRecordFlags != 0 {
		// Encode Flags
		e.flagsEncoder.Encode(val.flags)
	}

	if fieldMask&fieldModifiedLogRecordTraceID != 0 {
		// Encode TraceID
		e.traceIDEncoder.Encode(val.traceID)
	}

	if fieldMask&fieldModifiedLogRecordSpanID != 0 {
		// Encode SpanID
		e.spanIDEncoder.Encode(val.spanID)
	}

	if fieldMask&fieldModifiedLogRecordEventName != 0 {
		// Encode EventName
		e.eventNameEncoder.Encode(val.eventName)
	}

	// Account written bits in the limiter.
	e.limiter.AddFrameBits(bitCount)

	// Mark all fields non-modified so that next Encode() correctly
	// encodes only fields that change after this.
	val.modifiedFields.mask = 0
}

// CollectColumns collects all buffers from all encoders into buf.
func (e *LogRecordEncoder) CollectColumns(columnSet *pkg.WriteColumnSet) {
	columnSet.SetBits(&e.buf)
	colIdx := 0
	// Collect TimeUnixNano field.
	if e.fieldCount <= 0 {
		return // TimeUnixNano and subsequent fields are skipped.
	}
	e.timeUnixNanoEncoder.CollectColumns(columnSet.At(colIdx))
	colIdx++
	// Collect ObservedTimeUnixNano field.
	if e.fieldCount <= 1 {
		return // ObservedTimeUnixNano and subsequent fields are skipped.
	}
	e.observedTimeUnixNanoEncoder.CollectColumns(columnSet.At(colIdx))
	colIdx++
	// Collect SeverityNumber field.
	if e.fieldCount <= 2 {
		return // SeverityNumber and subsequent fields are skipped.
	}
	e.severityNumberEncoder.CollectColumns(columnSet.At(colIdx))
	colIdx++
	// Collect SeverityText field.
	if e.fieldCount <= 3 {
		return // SeverityText and subsequent fields are skipped.
	}
	e.severityTextEncoder.CollectColumns(columnSet.At(colIdx))
	colIdx++
	// Collect Body field.
	if e.fieldCount <= 4 {
		return // Body and subsequent fields are skipped.
	}
	if !e.isBodyRecursive {
		e.bodyEncoder.CollectColumns(columnSet.At(colIdx))
		colIdx++
	}
	// Collect Attributes field.
	if e.fieldCount <= 5 {
		return // Attributes and subsequent fields are skipped.
	}
	if !e.isAttributesRecursive {
		e.attributesEncoder.CollectColumns(columnSet.At(colIdx))
		colIdx++
	}
	// Collect DroppedAttributesCount field.
	if e.fieldCount <= 6 {
		return // DroppedAttributesCount and subsequent fields are skipped.
	}
	e.droppedAttributesCountEncoder.CollectColumns(columnSet.At(colIdx))
	colIdx++
	// Collect Flags field.
	if e.fieldCount <= 7 {
		return // Flags and subsequent fields are skipped.
	}
	e.flagsEncoder.CollectColumns(columnSet.At(colIdx))
	colIdx++
	// Collect TraceID field.
	if e.fieldCount <= 8 {
		return // TraceID and subsequent fields are skipped.
	}
	e.traceIDEncoder.CollectColumns(columnSet.At(colIdx))
	colIdx++
	// Collect SpanID field.
	if e.fieldCount <= 9 {
		return // SpanID and subsequent fields are skipped.
	}
	e.spanIDEncoder.CollectColumns(columnSet.At(colIdx))
	colIdx++
	// Collect EventName field.
	if e.fieldCount <= 10 {
		return // EventName and subsequent fields are skipped.
	}
	e.eventNameEncoder.CollectColumns(columnSet.At(colIdx))
	colIdx++
}

