// Continue is called at the start of the frame to continue decoding column data.
// This should set the decoder's source buffer, so the new decoding continues from
// the supplied column data. This should NOT reset the internal state of the decoder,
// since columns can cross frame boundaries and the new column data is considered
// continuation of that same column in the previous frame.
func (d *LogRecordDecoder) Continue() {
	d.buf.Reset(d.column.Data())

	if d.fieldCount <= 0 {
		return // TimeUnixNano and subsequent fields are skipped.
	}
	d.timeUnixNanoDecoder.Continue()
	if d.fieldCount <= 1 {
		return // ObservedTimeUnixNano and subsequent fields are skipped.
	}
	d.observedTimeUnixNanoDecoder.Continue()
	if d.fieldCount <= 2 {
		return // SeverityNumber and subsequent fields are skipped.
	}
	d.severityNumberDecoder.Continue()
	if d.fieldCount <= 3 {
		return // SeverityText and subsequent fields are skipped.
	}
	d.severityTextDecoder.Continue()
	if d.fieldCount <= 4 {
		return // Body and subsequent fields are skipped.
	}

	if !d.isBodyRecursive {
		d.bodyDecoder.Continue()
	}

	if d.fieldCount <= 5 {
		return // Attributes and subsequent fields are skipped.
	}

	if !d.isAttributesRecursive {
		d.attributesDecoder.Continue()
	}

	if d.fieldCount <= 6 {
		return // DroppedAttributesCount and subsequent fields are skipped.
	}
	d.droppedAttributesCountDecoder.Continue()
	if d.fieldCount <= 7 {
		return // Flags and subsequent fields are skipped.
	}
	d.flagsDecoder.Continue()
	if d.fieldCount <= 8 {
		return // TraceID and subsequent fields are skipped.
	}
	d.traceIDDecoder.Continue()
	if d.fieldCount <= 9 {
		return // SpanID and subsequent fields are skipped.
	}
	d.spanIDDecoder.Continue()
	if d.fieldCount <= 10 {
		return // EventName and subsequent fields are skipped.
	}
	d.eventNameDecoder.Continue()
}

func (d *LogRecordDecoder) Reset() {

	if d.fieldCount <= 0 {
		return // TimeUnixNano and all subsequent fields are skipped.
	}
	d.timeUnixNanoDecoder.Reset()
	if d.fieldCount <= 1 {
		return // ObservedTimeUnixNano and all subsequent fields are skipped.
	}
	d.observedTimeUnixNanoDecoder.Reset()
	if d.fieldCount <= 2 {
		return // SeverityNumber and all subsequent fields are skipped.
	}
	d.severityNumberDecoder.Reset()
	if d.fieldCount <= 3 {
		return // SeverityText and all subsequent fields are skipped.
	}
	d.severityTextDecoder.Reset()
	if d.fieldCount <= 4 {
		return // Body and all subsequent fields are skipped.
	}

	if !d.isBodyRecursive {
		d.bodyDecoder.Reset()
	}

	if d.fieldCount <= 5 {
		return // Attributes and all subsequent fields are skipped.
	}

	if !d.isAttributesRecursive {
		d.attributesDecoder.Reset()
	}

	if d.fieldCount <= 6 {
		return // DroppedAttributesCount and all subsequent fields are skipped.
	}
	d.droppedAttributesCountDecoder.Reset()
	if d.fieldCount <= 7 {
		return // Flags and all subsequent fields are skipped.
	}
	d.flagsDecoder.Reset()
	if d.fieldCount <= 8 {
		return // TraceID and all subsequent fields are skipped.
	}
	d.traceIDDecoder.Reset()
	if d.fieldCount <= 9 {
		return // SpanID and all subsequent fields are skipped.
	}
	d.spanIDDecoder.Reset()
	if d.fieldCount <= 10 {
		return // EventName and all subsequent fields are skipped.
	}
	d.eventNameDecoder.Reset()
}

func (d *LogRecordDecoder) Decode(dstPtr *LogRecord) error {
	val := dstPtr

	// Read bits that indicate which fields follow.
	val.modifiedFields.mask = d.buf.PeekBits(d.fieldCount)
	d.buf.Consume(d.fieldCount)

	if val.modifiedFields.mask&fieldModifiedLogRecordTimeUnixNano != 0 { // TimeUnixNano is changed.

		if err := d.timeUnixNanoDecoder.Decode(&val.timeUnixNano); err != nil {
			return err
		}
	}

	if val.modifiedFields.mask&fieldModifiedLogRecordObservedTimeUnixNano != 0 { // ObservedTimeUnixNano is changed.

		if err := d.observedTimeUnixNanoDecoder.Decode(&val.observedTimeUnixNano); err != nil {
			return err
		}
	}

	if val.modifiedFields.mask&fieldModifiedLogRecordSeverityNumber != 0 { // SeverityNumber is changed.

		if err := d.severityNumberDecoder.Decode(&val.severityNumber); err != nil {
			return err
		}
	}

	if val.modifiedFields.mask&fieldModifiedLogRecordSeverityText != 0 { // SeverityText is changed.

		if err := d.severityTextDecoder.Decode(&val.severityText); err != nil {
			return err
		}
	}

	if val.modifiedFields.mask&fieldModifiedLogRecordBody != 0 { // Body is changed.

		if val.body == nil {
			if err := d.allocators.allocSizeChecker.PrepAllocSize(uint(unsafe.Sizeof(*val.body))); err != nil {
				return err
			}
			val.body = d.allocators.AnyValue.Alloc()
			val.body.init(&val.modifiedFields, fieldModifiedLogRecordBody)
		}

		if err := d.bodyDecoder.Decode(val.body); err != nil {
			return err
		}
	}

	if val.modifiedFields.mask&fieldModifiedLogRecordAttributes != 0 { // Attributes is changed.

		if err := d.attributesDecoder.Decode(&val.attributes); err != nil {
			return err
		}
	}

	if val.modifiedFields.mask&fieldModifiedLogRecordDroppedAttributesCount != 0 { // DroppedAttributesCount is changed.

		if err := d.droppedAttributesCountDecoder.Decode(&val.droppedAttributesCount); err != nil {
			return err
		}
	}

	if val.modifiedFields.mask&fieldModifiedLogRecordFlags != 0 { // Flags is changed.

		if err := d.flagsDecoder.Decode(&val.flags); err != nil {
			return err
		}
	}

	if val.modifiedFields.mask&fieldModifiedLogRecordTraceID != 0 { // TraceID is changed.

		if err := d.traceIDDecoder.Decode(&val.traceID); err != nil {
			return err
		}
	}

	if val.modifiedFields.mask&fieldModifiedLogRecordSpanID != 0 { // SpanID is changed.

		if err := d.spanIDDecoder.Decode(&val.spanID); err != nil {
			return err
		}
	}

	if val.modifiedFields.mask&fieldModifiedLogRecordEventName != 0 { // EventName is changed.

		if err := d.eventNameDecoder.Decode(&val.eventName); err != nil {
			return err
		}
	}

	return d.buf.Error()
}

// LogRecordAllocator implements a custom allocator for LogRecord.
// It maintains a pool of pre-allocated LogRecord and grows the pool
// dynamically as needed, up to a maximum size of 64 elements.
type LogRecordAllocator struct {
	pool []LogRecord
	ofs  int
}

// Alloc returns the next available LogRecord from the pool.
// If the pool is exhausted, it grows the pool by doubling its size
// up to a maximum of 64 elements.
func (a *LogRecordAllocator) Alloc() *LogRecord {
	if a.ofs < len(a.pool) {
		// Get the next available LogRecord from the pool
		a.ofs++
		return &a.pool[a.ofs-1]
	}
	// We've exhausted the current pool, prealloc a new pool.
	return a.prealloc()
}

//go:noinline
func (a *LogRecordAllocator) prealloc() *LogRecord {
	// prealloc expands the pool by doubling its size, up to a maximum of 64 elements.
	// If the pool is empty, it starts with 1 element.
	newLen := min(max(len(a.pool)*2, 1), 64)
	a.pool = make([]LogRecord, newLen)
	a.ofs = 1
	return &a.pool[0]
}
